        if (bio.wings && affl.some(a => /wing/.test(a.zone || '') && (a.kind === 'fracture' || a.kind === 'amputated' || a.sev >= 2))) locks.push({ text: 'A wing is hurt — CANNOT fly. Gliding down, at best.', zone: 'l_wing' });
        if (con < 0.3) locks.push({ text: 'Unconscious — CANNOT act, speak or decide until woken.', zone: 'head' });
        if (S.blood < 40 && bio.bleeds) locks.push({ text: 'Too little blood — any effort brings collapse. Rest does not fix this; blood or healing does.', zone: 'chest' });
        if (S.awake >= 96 && bio.tires) locks.push({ text: 'The body forces sleep — no will, Authority or Divine Protection stops it.', zone: 'head' });
