        if (bad(os('heart'))) locks.push({ text: 'Heart hurt — CANNOT sprint or fight for long; hard effort brings collapse.', zone: 'chest' });
        if (os('gate') === 'damaged') locks.push({ text: 'Gate damaged — magic through it strains and hurts; the world\u2019s own rule for a damaged Gate applies.', zone: 'chest', organ: 'gate' });
