        if (os('horns') === 'broken' || os('horns') === 'lost') locks.push({ text: 'Horn broken — CANNOT draw power through it; the race\u2019s own law for a lost horn applies.', zone: 'head', organ: 'horns' });
        if (os('core') === 'damaged') locks.push({ text: 'Core cracked — it holds your life: one more blow there may end you.', zone: 'chest', organ: 'core' });
